) AS (
  VALUES 
    (436::BIGINT, 'Muy bien profesor, explica bien y califica muy suave. Hace todo en el gaap y siempre brinda ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-08T00:00:00+00:00'::TIMESTAMPTZ, '093cecbcbef4c467a045b43d428baa7926d696672fa4bbb65600c5f053c53d74'::TEXT, ARRAY[963]::BIGINT[]),
    (436::BIGINT, 'El profe es muy buena persona, te va a ayudar y siempre se preocupa por los estudiantes. Sin embargo, como profe si le cuesta y no explica tan claro, aveces se desvía del tema pero cuestión de prestar mucha atención y si no te queda claro preguntar. Se pasa bastante fácil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '628bcd0a2c271424a94b81ccfbb5ed2baab74ada83542331b1631bfef42adb38'::TEXT, ARRAY[1719]::BIGINT[]),
    (436::BIGINT, 'El profe es buena gente pero como profesor no lo sé, hace comentarios/chistes un toque machistas sin darse cuenta, sentí que no aprendí mucho, era difícil que le ayudara a uno, siempre decía que luego por qué no le alcanzaba el tiempo, se pasa fácil pero no se aprende nada'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'bfd557c8a8f205a0d2870163e0bbad61fa06df67684692c98c0ba2fb40738a08'::TEXT, ARRAY[1446]::BIGINT[]),
    (436::BIGINT, 'El profesor es muy buena persona, se preocupa mucho por el estudiante y por ayudarlo. Sin embargo, como profesor deja mucho que desear, explicaciones confusas, solo lee de diapositivas, es sumamente desordenado y hay que andar detras de él para que corrija evaluaciones. Fácil de pasar, no se aprende'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'e95358b229eb45581df63c82ce3bc65885d3559cd27a8d4394e1a053630d4ee2'::TEXT, ARRAY[1446]::BIGINT[]),
    (436::BIGINT, 'Es muy buen profe y buena persona en general, es muy atento. La carga y el curso se hacen llevaderos con él. Volvería a llevar un curso con él. Lo único malo es que es un poquito desordenado y no suele trabajar con rúbrica'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '046121ca226b59f0f4354a0d8f3ea37b1058fe85a276c60895ebdc50abdf46c3'::TEXT, ARRAY[1446]::BIGINT[]),
    (436::BIGINT, 'El profe explica bien, pero en muchos temas lo que hizo fue leer diapositivas, el curso se pasa bastante fácil pero considero que no se aprende lo suficiente.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '13649c5df627d707b03dddeeb48435ec8640fbfc9a3b4c8556357e44b7ab7e14'::TEXT, ARRAY[1446]::BIGINT[]),
    (436::BIGINT, 'Es un buen profe, trabajos cortos y los exámenes son fáciles, se pasa fácil con el.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'eae8c5bad4d212270b4fcfdccbac5f7bae5713acfb802d133bbce986985ea88f'::TEXT, ARRAY[963]::BIGINT[]),
    (436::BIGINT, 'Muy buena persona, pero mal profe. Deja MUCHOS trabajos. Las clases son largas, aburridas y poco prácticas.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-11-12T00:00:00+00:00'::TIMESTAMPTZ, '746aacd937706c13a9ed89c7dd88c987d322343d706afdad3c8641166a1e359b'::TEXT, ARRAY[1736]::BIGINT[]),
    (436::BIGINT, 'Es un muy buen profe, explica bien, suele ser una clase un tanto aburrida. Los exámenes, tareas y quiz son muy fáciles si usted entiende la materia, no hace nada más difícil que lo que ve en clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'ef8cd51f2ba2e959e1eabde88b06db535db34e5de4b45def9fe124c19ff0730c'::TEXT, ARRAY[963]::BIGINT[]),
    (436::BIGINT, 'Sus evaluaciones a veces no son claras, es buena gente pero cuando le hacen consultas cuesta demasiado que entienda lo que uno le está preguntando. No me parece buen profesor pero va a pasar el curso fácilmente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '25ad085ed761666b0104c983d4449dc3e5fa845acdd4f6053e1cfe6cd6f4e059'::TEXT, ARRAY[963]::BIGINT[]),
    (436::BIGINT, 'Nota muy baja en mi opinión porque es un profe muy pura vida. Se nota su interés por la materia, y de que los estudiantes no solo pasen, sino de que aprendan. El curso en si es fácil, y con este profe se pasa caminando. Matricule con él sin duda'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'c037f825f92dbcce91a17919933aa7771943755766312064e7cb32c696724e5e'::TEXT, ARRAY[963]::BIGINT[]),
    (436::BIGINT, 'Excelente persona y profesor, las clases son excelentes. Deja tareas y quices semanales que refuerzan lo visto en clase. Si se lleva al día y se cumple con todas las evaluaciones se aprueba el curso'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'b11ae2ed5821aee322200bd3f0ea8d9120811fc6e73297a7d23eebaeefc3b9db'::TEXT, ARRAY[963]::BIGINT[]),
    (436::BIGINT, 'Como persona es super agradable. Como profesor debe mejorar sus métodos de enseñanza. Igualmente el curso se pasa relajado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-10-14T00:00:00+00:00'::TIMESTAMPTZ, 'e8b8c651b4ad71e7ed98294453be5113638c07da37ccad283b16a7c82ce46889'::TEXT, ARRAY[1722]::BIGINT[]),
    (436::BIGINT, 'Ayuda mucho en la hora estudiante, diría que hasta mas que en clases regulares. Si no puedes ir estas jodido. Examenes y quices a base de todo lo visto pero si no sabes estudiar te ira mal. Clases aburridas pero es normal ya que el curso es heavy de teoría.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5e237b3b1ba4a96c6036bcf39d9b9b5736d348e81abb480ac762d313bcf95a47'::TEXT, ARRAY[1719, 1722]::BIGINT[]),
    (436::BIGINT, 'Pasar el curso con el es muy fácil ,pero va a aprender muy poco.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ff63767da46904ad6e59163cb1e498f9953fe0384203f2d8fbe781d00a23ae64'::TEXT, ARRAY[1722, 1719]::BIGINT[]),
    (436::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2022-05-28T00:00:00+00:00'::TIMESTAMPTZ, '6bf39915f8b1e5565d8f1c0e03e868969907e9cd3482a80b7b05121d2a021e7c'::TEXT, ARRAY[1791]::BIGINT[]),
    (436::BIGINT, 'Es un muy buen profe, lo reviví virtual. Sin embargo creo que estudiantes de San Carlos buscan desestimarlo. El curso es fácil y el es muy comprensible con las evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'd75afed4f2430aa26652d20af78fe480943271a3a90ae73ce02cab8a0601b967'::TEXT, ARRAY[1751, 1312]::BIGINT[]),
    (436::BIGINT, 'Demasiado facil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '065987220b953a1000abb96453f018fdffe4a0dc49da37316799c4eaa8edf907'::TEXT, ARRAY[1773]::BIGINT[]),
    (436::BIGINT, 'Muy buen profesor, interesado por que uno aprenda y muy buena persona. La mayoría de malos comentarios lastimosamente son de personas de la sede de San Carlos, ya que por su actitud en clases parece que quieren que les regalen todo y parece que no se dan cuenta que están en la universidad.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c657c24106a805215a682803902bfd5fd4fc58b9c6927f2313ddc55e692ee299'::TEXT, ARRAY[1751, 1312]::BIGINT[]),
    (436::BIGINT, 'Los cursos con él se vuelven bastante aburridos, todo es pura diapositivas, además lo que viene en los examenes es demaaasiado diferente a lo visto en clase, no es flexible con fechas de entregas. Y hace bromas innecesarias y comentarios nada que ver. Pero el curso se pasa'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2021-07-29T00:00:00+00:00'::TIMESTAMPTZ, '675da05c98d241ab3edcbee65444954f7fee84ca6266cf8214ee3a2aafa4bcc5'::TEXT, ARRAY[1719, 1736]::BIGINT[]),
    (436::BIGINT, 'Me sorprende la nota tan baja que tiene, es buen profe, muy buena nota y ayuda bastante. No califica duro y la mayoría de cosas las explica bastante claro.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ba526f43b98e7e92cc38329bb48803a5d57b78f862182e69e83b5e7b1874aa53'::TEXT, ARRAY[1722]::BIGINT[]),
    (436::BIGINT, 'El profe en sí tiene buenas intenciones y trata que el estudiante aprenda bastante, no solo en los temas del curso sino con temas de la carrera en general, deja evaluaciones como lecturas, charlas, vídeos, para aprender de la carrera. La clase es larga y deja muy poco tiempo para hacer los exámenes'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'e00664ba0e5ed69e6bc0d8ebf8e818979fd621687dc721855e6ae2cccb4949bd'::TEXT, ARRAY[1736]::BIGINT[]),
    (436::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-04-11T00:00:00+00:00'::TIMESTAMPTZ, 'a7f15931a2ca32bdb4e335c200cc78be3e9a386de06513a0d46d1b55efc533fb'::TEXT, ARRAY[1776, 1770, 2635]::BIGINT[]),
    (436::BIGINT, 'La materia la da básicamente en diapositivas. LES RECOMIENDO pasar metidos en la oficina, por consultas. Estudiar TODO, si pueden evitarlo, mejor. En general no lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'f9b8969fcdfe3e7f3a1298313361c8a20da5cf9e7a190fec7502a1a82bc1e8be'::TEXT, ARRAY[1719, 1722]::BIGINT[]),
    (436::BIGINT, 'No es el mejor profe del mundo, las preguntas de los exámenes son sacadas de alguna práctica o tarea moral. Sus clases es sentarse a escuchar leer una presentación. Mientras da la materia da muchos ejemplos muy prácticos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'b8a7fb5b64c17301875b7bea172d66d59f1885306c5de5af218fd10917ea43f8'::TEXT, ARRAY[1719, 1722]::BIGINT[]),
    (436::BIGINT, 'Muy Buen profesor, aprende de sus errores pasados, se prepara antes de dar las clases no se pone a leer las presentaciones como en Costos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2019-10-16T00:00:00+00:00'::TIMESTAMPTZ, '3889d76e4626e681b65dd49f7f0df0cdb4b5bf706d577b6c5d7554f6059d0b99'::TEXT, ARRAY[2622]::BIGINT[]),
    (436::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'fde601bc0501d79d51a3396b25077f9c992e2a44b9a223f545fc8503be7538f8'::TEXT, ARRAY[4838]::BIGINT[]),
    (436::BIGINT, 'No domina los temas, no ayuda al estudiante, se desentiende del estudiante y no contesta mensajes ni llamadas, te deja en visto, le falta mucha actualización de tecnologías, no aporta ninguna recomendación ni seguimiento al estudiante, es buena persona pero como profesor no es para el TEC'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2018-11-13T00:00:00+00:00'::TIMESTAMPTZ, '2eb0ce5eab1b5ff692cc1ef775af33162a51ac966cbeb9dddaa026a314d0b072'::TEXT, ARRAY[1803]::BIGINT[]),
    (436::BIGINT, 'Apesar de que no es tan bueno explicando es muy buena persona y se interesa porque los estudiantes aprendan, el curso puede o volverse muy facil o muy tedioso'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'ecb4cb3f60130572acc7cbd9fc6eb44020fc71162787071bc76a7dbadd4621ec'::TEXT, ARRAY[2622]::BIGINT[]),
    (436::BIGINT, 'No tiene el dominio del tema, por lo que intenta pero le cuesta mucho aclarar dudas. Hace los exámenes con la intención de perjudicar al estudiante, ya que en ocasiones mete ejercicios que no se comparan nada al del nivel de dificultad que tienen los de la clase. Sin embargo el curso es pasable.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '05b8f8884e00184248b43c74105132a647f1552d9c47643905b14307729790e6'::TEXT, ARRAY[2622]::BIGINT[]),
    (436::BIGINT, 'Alguno de los tres examenes los hace difícil, y no se parece a lo que explica en clase. Es buena gente, pero no tiene mucho dominio del tema. Ayuda con las tareas. El problema es que si no se piensa como el, pone las cosas malas'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f08c9bdf55712e4b90fa023f7b16fbb9ed7a9b458ee8c2b2416b63123df2db4f'::TEXT, ARRAY[1746]::BIGINT[]),
    (436::BIGINT, 'Un desastre, Califica poco claro y si no es lo que el esta pensando en el momento que esta calificando esta malo. No razona y tiene poco dominio de la materia, Es muy malo. Eso si es buena gente y cuenta chistes en clase'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'cc73d209bc10cfa30d909256c9d0bf0e95bcee268f8c2f8752498810cb3e0874'::TEXT, ARRAY[1719]::BIGINT[]),
    (436::BIGINT, 'No domina la materia cuando le preguntan algo complicado te despista enviando a leer el libro...'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '50a9c813a45074ff97934176165f33a8abba1125164172ea7ae59644b00aa415'::TEXT, ARRAY[1728]::BIGINT[]),
    (436::BIGINT, 'En los exámenes no sale nada que no se haya visto en clase, haciendo la práctica que el da se logra ganar con el curso...Es buen profe, intenta ayudar al estudiante e intenta que las clases no sean aburridas, el curso no es de asistencia sin embargo por medio de ella ve el interés del estudiante.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'df871598225268a372e824354f87fe86f7876017fa8f98ea9ab2cb0d6112a288'::TEXT, ARRAY[1728]::BIGINT[]),
    (436::BIGINT, 'Califica muy rudo para lo que enseña.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'da8eb7a8f03a98aa8a0c7b9b6ab069901ef7dfc59e56a0d6c96b30b7af1c5b5f'::TEXT, ARRAY[963]::BIGINT[]),
    (436::BIGINT, 'Es bastante paciente y trata de hacer la clase entretenida. Aunque la clase sea no obligatoria le importa la asistencia. Ayuda mucho, le gusta la participación. Es un profesor bastante bueno y es una muy buena persona. Los exámenes son muy similares a los ejercicios de clase nada fuera de lo común .'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2017-01-28T00:00:00+00:00'::TIMESTAMPTZ, '2704a0aa6fd6d0a8a22a3a01d8703a69f912d53e00c26cf7e7657be63935d1ad'::TEXT, ARRAY[963]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
